// Sessiebreed undo/redo op delta's ({added, removed}) — gelijk voor
// OPFS-bronnen en SPARQL-endpoints (de aanroeper persisteert de teruggegeven
// inverse delta zelf via bron-sync).
//
// Groeperingsmechanisme: log.groep(fn) voegt alle noteer-aanroepen binnen fn
// samen tot één logstap, zodat replaceSubjectClosure (die twee deltas meldt)
// als één undo-stap terugdraait. Chronologie BLIJFT behouden: per delta
// in OMGEKEERDE volgorde voor undo, VOORWAARTSE volgorde voor redo.
//
// FOUTAFHANDELING: mutaties halverwege een groep-fn worden bewaard, zodat undo
// ze kan herstellen. Groep sluit de lopende stap af en geeft de fout door aan
// de aanroeper (de store staat dan deels gemuteerd; dat is goed — undo
// herstelt alles).
//
// Geneste groepen: diepteteller zodat alleen de BUITENSTE groep sluit.
// Lege groep (geen noteer) → geen stap.

import * as N3 from 'n3';

export function maakLog(store) {
  // Een STAP is {id, deltas}. Het id is de golf-B-inlossing van de grens die
  // hieronder bij vergeetLaatste beschreven staat: het foutpad van een trage
  // bron-sync kan er de stap mee aanwijzen die WERKELIJK mislukte, in plaats
  // van aan te nemen dat dat de laatste is. `noteer` geeft hem terug; binnen
  // een groep krijgen alle deltas van die groep hetzelfde id, want zij zijn
  // samen één ongedaan-stap.
  const gedaan = [], hersteld = [];
  let groepDiepte = 0;
  let lopendeLijst = [];  // Huidige groep-deltas; leeg buiten groep
  let volgendId = 0;
  let lopendId = 0;       // Het id van de groep die nu open staat, 0 = geen

  const nieuweStap = (deltas, id) => ({ id, deltas });

  const inverse = (d) => ({ added: d.removed, removed: d.added });

  const pas = (d) => {
    store.removeQuads(d.removed);
    store.addQuads(d.added);
  };

  const ontdubbelInverses = (alleToegevoegd, alleVerwijderd) => {
    // Ontdubbelen: quads die in beide lijsten voorkomen heffen elkaar op, en
    // een quad die twee keer in dezelfde lijst staat telt één keer.
    //
    // NIET op q.toString() sleutelen: N3-quads erven toString() van
    // Object.prototype en leveren dus voor élke quad "[object Object]" —
    // dan filteren beide lijsten elkaar volledig weg en is de inverse van een
    // gemengde stap (de vervang-vorm: remove-dan-add) leeg, terwijl de
    // aanroeper juist die delta persisteert. Sleutel per TERM, zoals
    // parse.js' dedupeTriples; de graph hoort erbij, want twee bronnen kunnen
    // hetzelfde triple in verschillende graphs bevatten.
    const sleutel = (q) => N3.termToId(q.subject) + ' ' + N3.termToId(q.predicate)
      + ' ' + N3.termToId(q.object) + ' ' + N3.termToId(q.graph);

    const toegevoegdSet = new Set(alleToegevoegd.map(sleutel));
    const verwijderdSet = new Set(alleVerwijderd.map(sleutel));

    const netto = (lijst, tegen) => {
      const gezien = new Set();
      const uit = [];
      for (const q of lijst) {
        const k = sleutel(q);
        if (tegen.has(k) || gezien.has(k)) continue;
        gezien.add(k);
        uit.push(q);
      }
      return uit;
    };

    return {
      added: netto(alleToegevoegd, verwijderdSet),
      removed: netto(alleVerwijderd, toegevoegdSet),
    };
  };

  return {
    /** Noteer één delta en geef het STAP-ID terug waarin hij landt. Binnen een
     *  groep is dat voor elke delta hetzelfde id: de groep is één undo-stap. */
    noteer(delta) {
      if (groepDiepte > 0) {
        if (!lopendId) lopendId = ++volgendId;
        lopendeLijst.push(delta);
        return lopendId;
      }
      const id = ++volgendId;
      gedaan.push(nieuweStap([delta], id));
      hersteld.length = 0;
      return id;
    },

    // De rollback-ingang: haal de laatst genoteerde stap uit het log ZONDER
    // hem toe te passen. Voor het foutpad — een geweigerde SPARQL Update of
    // een mislukte schrijfactie — waar de aanroeper de store zelf al heeft
    // teruggerold. Zonder dit blijft de stap in `gedaan` staan en kan redo
    // (na een undo) een triple herleven dat nooit gepersisteerd is.
    //
    // SEMANTIEK:
    //  - popt precies één stap van de gedaan-stapel en gooit hem weg;
    //  - past NIETS toe op de store (de aanroeper deed de rollback al) en
    //    geeft dus ook geen delta terug — alleen true/false of er iets weg is;
    //  - raakt de redo-stapel NIET: de vergeten stap stond op `gedaan` en is
    //    daar nooit vandaan gehaald, dus `hersteld` bevat hem niet. Een
    //    eerdere redo-stapel hoort intact te blijven — de mislukte mutatie
    //    had hem via noteer() al gewist, en die wissing terugdraaien kan niet.
    //  - binnen een lopende groep vergeet hij de laatste delta van die groep
    //    (die is nog niet als stap afgesloten).
    // GRENS: hij vergeet de LAATSTE stap, niet noodzakelijk de mislukte. Komt
    // er tussen de mutatie en de foutmelding van de bron-sync nóg een mutatie
    // binnen, dan vergeet hij de verkeerde. Gebruik daarom `vergeetStap(id)`
    // waar het id bekend is; deze vorm blijft staan voor het geval dat het niet
    // is (een fout zonder aanwijsbare stap).
    vergeetLaatste() {
      if (groepDiepte > 0) return lopendeLijst.pop() !== undefined;
      return gedaan.pop() !== undefined;
    },

    /** DE GERICHTE ROLLBACK-INGANG (golf B, checklistpunt 2). Vergeet de stap
     *  met dit id, waar hij ook in de stapel staat — dezelfde semantiek als
     *  `vergeetLaatste` (niets toepassen, redo-stapel met rust), maar zonder de
     *  aanname dat de mislukte mutatie de laatste is.
     *
     *  WANNEER DAT VERSCHIL BIJT: een salvo met een TRAGE bron-sync. De
     *  gebruiker typt in twee velden; de eerste schrijfactie is nog onderweg
     *  wanneer de tweede mutatie al genoteerd is. Weigert de bron dan de
     *  EERSTE, dan gooit `vergeetLaatste` de TWEEDE (geslaagde) stap weg: die
     *  is daarna niet meer ongedaan te maken, en de mislukte staat er nog wel
     *  — precies omgekeerd aan wat er hoort te gebeuren.
     *
     *  Een onbekend id (de stap is al door undo van de stapel gehaald, of het
     *  foutpad hoorde bij een undo-delta die nooit genoteerd is) levert
     *  `false`: dan valt er niets te vergeten, en dat is geen fout. */
    vergeetStap(id) {
      if (!id) return false;
      if (groepDiepte > 0 && id === lopendId) {
        if (!lopendeLijst.length) return false;
        lopendeLijst = [];
        lopendId = 0;
        return true;
      }
      const i = gedaan.findIndex((s) => s.id === id);
      if (i < 0) return false;
      gedaan.splice(i, 1);
      return true;
    },

    groep(fn) {
      groepDiepte++;
      try {
        fn();
      } catch (e) {
        // Fout halverwege: behoud de al genoteerde deltas door de stap af te sluiten
        if (lopendeLijst.length > 0) {
          gedaan.push(nieuweStap([...lopendeLijst], lopendId || ++volgendId));
          hersteld.length = 0;
          lopendeLijst = [];
          lopendId = 0;
        }
        throw e;  // Geef de fout door aan de aanroeper
      } finally {
        groepDiepte--;
        // Alleen buitenste groep sluit de stap; alleen als deltas bestaan
        if (groepDiepte === 0 && lopendeLijst.length > 0) {
          gedaan.push(nieuweStap([...lopendeLijst], lopendId || ++volgendId));
          hersteld.length = 0;
          lopendeLijst = [];
          lopendId = 0;
        }
        if (groepDiepte === 0) lopendId = 0;
      }
    },

    undo() {
      const stap = gedaan.pop();
      if (!stap) return null;

      hersteld.push(stap);

      // Pas de inverses in OMGEKEERDE volgorde toe. Reverse op een KOPIE: de
      // stap staat inmiddels op `hersteld` en redo moet hem voorwaarts vinden.
      const alleToegevoegd = [];
      const alleVerwijderd = [];

      for (const d of [...stap.deltas].reverse()) {
        const inv = inverse(d);
        pas(inv);
        alleToegevoegd.push(...inv.added);
        alleVerwijderd.push(...inv.removed);
      }

      return ontdubbelInverses(alleToegevoegd, alleVerwijderd);
    },

    redo() {
      const stap = hersteld.pop();
      if (!stap) return null;

      gedaan.push(stap);

      // Pas deltas in VOORWAARTSE volgorde toe
      const alleToegevoegd = [];
      const alleVerwijderd = [];

      for (const d of stap.deltas) {
        pas(d);
        alleToegevoegd.push(...d.added);
        alleVerwijderd.push(...d.removed);
      }

      return ontdubbelInverses(alleToegevoegd, alleVerwijderd);
    },

    kanUndo: () => gedaan.length > 0,
    kanRedo: () => hersteld.length > 0,
  };
}
