// DE MUTATIEKERN: de bewerk-stand, één bewerkbron, en elke wijziging van de
// graaf op weg naar het scherm en naar de bron.
//
// Gedragsbron is het bewerk-STAND-blok van de bevroren viewer (doc.js:
// setEditMode/bevestigEditMode, bewerkbareStore, voerUit, herrenderNaMutatie,
// doeUndo/doeRedo) plus het fase C-ledger dat zegt waaróm. Wat hier ANDERS is
// dan daar, en met opzet:
//
//  1. ÉÉN BEWERKBRON (spec dt3, besluit Michiel 6 sep). De bevroren viewer kende
//     meerdere read-write bronnen naast elkaar, met een keuzemenu en een
//     `schrijfbronGraph` om de gekozene te onthouden. Dat is vervallen: er is
//     precies één bewerkbare bron, elke mutatie en elke toevoeging gaat
//     daarheen, en "gelockt" betekent voortaan één ding — "dit leeft niet in de
//     bewerkbron". De bewerkbaarheidstoets hieronder is navenant simpel.
//  2. DE HERRENDER IS EEN INVALIDATIE. `herrenderNu` in de viewer bouwde per
//     mutatie het hele model opnieuw en tekende de pagina opnieuw; hier meldt
//     de mutatie haar delta aan de corpusstore, die gericht herbouwt waar dat
//     kan (zie `invalideer` daar) en de rest aan Solid overlaat. Het
//     re-entrancy-slot en de één-diepe wachtrij komen ongewijzigd mee: die
//     bestaan omdat mutaties in salvo's komen (ingedrukte Ctrl+Z, een save die
//     meerdere velden raakt) en de weergave er niet twee keer tegelijk
//     doorheen moet lopen.
//  3. DE PROMISE VAN `voerUit` RESOLVET NÁ DE INVALIDATIE ÉN NA DE
//     DOM-VERVERSING. Dat moment is het haakje waar de scroll-stabiliteitsles
//     van fase C aan hangt: wie na een toevoeging wil weten waar de lezer staat,
//     moet kunnen wachten tot het beeld bij is.
//
// LAZY: deze module hoort NIET in de leeschunk. Niets in de leesviewer importeert
// haar statisch; de bewerkchrome haalt haar met een dynamische import binnen
// (spec §1, harde eis; golf B bewijst de grens met een bundelmeting).
import { batch, createEffect, createRoot, createSignal, on, untrack } from 'solid-js';
import { bewerkStore } from '../model/bewerkstore.js';
import { maakLog } from '../model/mutatielog.js';
import { maakBronSync } from '../model/bron-sync.js';
import { exportTurtle } from '../model/edit.js';
import { opfsWrite } from '../model/opfs.js';
import { sparqlUpdate, updateStatements } from '../model/sparql.js';
import { t } from '../model-grens.js';
import type { Delta, Graaf, Quad, Term } from '../model-grens.js';
import { graaf, invalideer } from './corpus.js';
import type { Invalidatie } from './corpus.js';
import {
  bewerkbron as bronbeheerBewerkbron, herstelBezig, koppelFlush,
} from './bronbeheer.js';
import { weergave, zetMelding, zetWeergave } from './weergave.js';

/** DE BEWERKBRON — de enige bron waarin geschreven wordt.
 *
 *  EIGENDOM: `stores/bronbeheer.ts` (lane-bronnen-edit). Die module beslist
 *  WELKE bron het is (slotjes als keuzerondje, ontgrendelen-via-kopie,
 *  werkbestand, endpoint-update-URL) en houdt het signaal vast; deze store
 *  LEEST hem en schrijft hem nooit. Deze vorm is `BronBewerk` daar, veld voor
 *  veld — hij staat hier omdat de twee modules in golf A in aparte lanes zijn
 *  gebouwd en de mutatiekern niet naar een bestand kan wijzen dat in zijn eigen
 *  boom nog niet bestaat. Zie `koppelBronbeheer` voor de naad. */
export interface Bewerkbron {
  /** De named graph waarin deze bron leeft — het routeeradres van elke delta. */
  graph: string;
  soort: 'ttl' | 'sparql';
  /** Afgeleid in bronbeheer: precies de bewerkbron staat op 'readwrite'. */
  modus: 'read' | 'readwrite';
  /** ttl-bron: de lokale kopie (OPFS) waar de autosave heen gaat. */
  opfs: string | null;
  name: string;
  url?: string;
  /** sparql-bron: waar een SPARQL Update heen moet. */
  updateUrl?: string;
}

/** De naad naar `stores/bronbeheer.ts`. Twee dingen gaan er overheen, en beide
 *  in de richting die de spec voorschrijft: het bewerkbron-SIGNAAL komt eruit
 *  (lezen, nooit schrijven) en de autosave-FLUSH gaat erin (`koppelFlush`, dat
 *  de vier plekken bedient waar een wachtende schrijfactie anders een verouderd
 *  bestand oplevert: vóór een download, vóór een her-ingest, vóór het weggooien
 *  van een bestand, en bij het loslaten van de bewerkbron).
 *
 *  FOLD 7 sep 2026: DICHTGETROKKEN. Beide modules staan in main, dus de naad
 *  is nu de echte import bovenaan dit bestand en `koppelDeBronnenlaag()`
 *  onderaan koppelt hem. De vorm bleek inderdaad veldgelijk — het was een
 *  regelvervanging, geen herontwerp.
 *
 *  `koppelBronbeheer` BLIJFT bestaan, en dat is geen restant: het is de
 *  injectieplek waarmee `bewerk.test.ts` een dubbel inhangt en waarmee
 *  `resetBewerkstand()` loskoppelt. Een interface met twee methodes is precies
 *  wat een test nodig heeft om de bevestigflow van beide kanten te kunnen
 *  duwen zonder een echte OPFS.
 *
 *  WAAROM DE KOPPELING HIER STAAT EN NIET IN `app.tsx`. Dat was de voor de hand
 *  liggende plek (`startBronbeheer()` staat daar), maar `app.tsx` zit in de
 *  LEESCHUNK en deze module niet: `stores/bewerk.ts` had bij de fold nog geen
 *  enkele importeur en stond dus in geen enkele chunk. Een aanroep vanuit
 *  `app.tsx` zou deze store én `model/edit.js` (13,6 kB) de leeschunk in
 *  trekken en de lazy-grens breken — de harde spec-eis van dit deeltraject.
 *  Andersom kost het niets: `bronbeheer.ts` is al eager, dus een import van
 *  lazy naar eager voegt geen byte aan de instap toe. Gemeten na deze ingreep:
 *  de leeschunk telt nog steeds 106 bronmodules en géén daarvan is
 *  bewerk-gerelateerd. */
export interface Bronbeheer {
  bewerkbron: () => Bewerkbron | null;
  koppelFlush: (fn: ((bron?: Bewerkbron | null) => Promise<void>) | null) => void;
  /** IS HET OPFS-HERSTEL VAN DE BEWERKBRON NOG ONDERWEG (bevinding A9)? Zolang
   *  dit waar is betekent `bewerkbron() === null` alleen "nog niet gelezen".
   *  OPTIONEEL, en dat is geen slordigheid: een dubbel dat de methode niet heeft
   *  gedraagt zich als "nee, klaar" — de stand van vóór deze bevinding, waarin
   *  elke bestaande test ongewijzigd blijft gelden. */
  herstelBezig?: () => boolean;
}

/** De schrijf-facade over de graaf: dezelfde leesmethoden als de store, maar
 *  elke schrijfactie landt in de graph van de bewerkbron en meldt zich als
 *  delta. Dit is wat een mutatiefunctie uit `model/edit.js` als eerste argument
 *  krijgt. De vorm staat hier omdat de modellaag JavaScript is (zelfde afspraak
 *  als model-grens.ts): één keer getypeerd in plaats van een cast per plek. */
export interface Schrijfstore {
  addQuad(...args: unknown[]): unknown;
  addQuads(quads: Quad[]): void;
  removeQuad(...args: unknown[]): unknown;
  removeQuads(quads: Quad[]): void;
  getQuads(s: unknown, p: unknown, o: unknown, g: unknown): Quad[];
  [sleutel: string]: unknown;
}

const maakBewerkStore = bewerkStore as unknown as (store: Graaf, opties: {
  graph?: string | null; onDelta?: ((d: Delta) => void) | null;
}) => Schrijfstore;

/** Eén melding van de bewerklaag, als SLEUTEL met variabelen — niet als tekst,
 *  zodat een taalwissel haar meeneemt. De statusregel van de leesviewer kent
 *  (nog) geen variabelen; meldingen zonder variabelen gaan daarom óók de
 *  bestaande weg op (`zetMelding`), de rest wacht op de bewerkchrome van golf B.
 *  SEAM: golf B mag deze twee kanalen samenvoegen. */
export interface Melding { sleutel: string; vars?: Record<string, unknown> }

// --- De stand ----------------------------------------------------------------

const [aanbodOpen, zetAanbodOpen] = createSignal(false);
const [melding, zetBewerkMelding] = createSignal<Melding | null>(null);
const [logVersie, zetLogVersie] = createSignal(0);
const [laatsteInvalidatie, zetLaatsteInvalidatie] = createSignal<Invalidatie | null>(null);
// A9: er is om de bewerkstand gevraagd terwijl het OPFS-herstel nog liep. Het
// oordeel is dus UITGESTELD, niet geveld — zie `zetEditMode`.
const [wachtOpHerstel, zetWachtOpHerstel] = createSignal(false);

export { aanbodOpen, laatsteInvalidatie, melding };

// De gekoppelde bronnenlaag. Zolang hij er niet is, is er geen bewerkbron en
// kan de bewerkstand dus niet aan — precies de stand van een leesviewer die de
// bewerklaag nog niet heeft ingeladen.
let bronbeheer: Bronbeheer | null = null;
let losKoppeling: (() => void) | null = null;

/** De bron waarin geschreven wordt, of `null` — dan kan de bewerkstand niet aan.
 *  Reactief: hij leest het signaal van bronbeheer. */
export function bewerkbron(): Bewerkbron | null {
  return bronbeheer ? bronbeheer.bewerkbron() : null;
}

/** Leest de bronnenlaag de bewerkbron nog terug uit OPFS (bevinding A9)? Dan is
 *  "er is geen bewerkbron" een MOMENTOPNAME en geen oordeel, en mag de
 *  bewerkstand er niet op afgebroken worden. */
function herstelOnderweg(): boolean {
  return !!(bronbeheer && bronbeheer.herstelBezig && bronbeheer.herstelBezig());
}

/** Staat de bewerkstand aan? De stand zelf woont in de weergavestore, want hij
 *  is deelbaar: `?edit=1` staat er al sinds deeltraject 2. */
export const editMode = (): boolean => weergave.editMode;

// DE TWEE MELDINGSKANALEN ZIJN SAMENGEVOEGD (golf B, de seam die hierboven bij
// `Melding` beschreven staat). Golf A stuurde alleen VARIABELELOZE meldingen
// door naar de statusregel, omdat die toen geen variabelen kende. Sinds de
// bronnen-edit-seam doet zij dat wel (`zetMelding(sleutel, vars)` +
// `meldingVars()`, en `status.tsx` geeft ze aan `tekst()` door), en dan is het
// achterhouden ervan geen voorzichtigheid meer maar een STIL FOUTPAD: juist de
// meldingen met variabelen zijn de scherpe — "wijziging niet bewaard in {bron}:
// {fout}". Die hoorde de lezer nergens.
//
// `melding()` blijft als eigen signaal bestaan: de bewerkchrome wil de laatste
// bewerkmelding kunnen tonen zonder mee te veranderen met wat de leesviewer
// verder op de statusregel zet.
function meld(sleutel: string, vars?: Record<string, unknown>): void {
  zetBewerkMelding({ sleutel, vars });
  zetMelding(sleutel, vars);
}

// Een weigering van een endpoint kan een halve HTML-foutpagina meebrengen
// (sparql.js neemt de eerste 200 tekens van de respons mee). Een melding is één
// regel: tags eruit, witruimte samengevouwen, en kappen.
function korteFout(bericht: unknown): string {
  const s = String(bericht ?? '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  return s.length > 160 ? `${s.slice(0, 160)}…` : s;
}

// --- De schrijfkant: facade, log en bron-sync --------------------------------
// Alle drie hangen aan hetzelfde paar: WELKE graaf en WELKE bewerkbron. Zodra
// er één verandert zijn ze ongeldig — de facade wijst dan naar de verkeerde
// graph, en het mutatielog houdt quads van een graaf die niet meer bestaat.

// De KALE graaf, zoals de modellaag hem aanlevert. De corpusstore geeft hem als
// ondoorzichtig object door; hier is hij precies zoveel store als deze module
// nodig heeft.
interface KaleStore {
  addQuads(quads: Quad[]): void;
  removeQuads(quads: Quad[]): void;
  getQuads(s: Term | null, p: Term | null, o: Term | null, g: Term | null): Quad[];
}

interface Wachtrij { verwerk(delta: Delta): Promise<void>; flush(bron?: Bewerkbron): Promise<void> }

let facade: Schrijfstore | null = null;
let log: ReturnType<typeof maakLog> | null = null;
let sync: Wachtrij | null = null;
let gebouwdVoor: { g: Graaf | null; bron: Bewerkbron | null } = { g: null, bron: null };

/** De opgespaarde delta van de mutaties die nog niet in de weergave staan. Eén
 *  invalidatie kan er meer dan één dragen: mutaties komen in salvo's en de
 *  wachtrij hieronder voegt ze samen. */
let wachtend: { added: Quad[]; removed: Quad[] } = { added: [], removed: [] };

function noteerVoorInvalidatie(delta: Delta): void {
  if (delta.added && delta.added.length) wachtend.added.push(...delta.added);
  if (delta.removed && delta.removed.length) wachtend.removed.push(...delta.removed);
}

// WELKE UNDO-STAP HOORT BIJ DEZE QUAD (golf B, checklistpunt 2). `opFout` deed
// `log.vergeetLaatste()` en nam daarmee aan dat de mislukte mutatie de laatste
// in het log is. Bij een salvo met een TRAGE bron-sync is dat niet waar: de
// tweede mutatie staat er al wanneer de eerste geweigerd wordt, en dan
// verdwijnt de geslaagde stap uit de geschiedenis terwijl de mislukte blijft.
//
// De weg terug loopt over de QUADS zelf, en dat kan omdat bron-sync de delta
// alleen HERGROEPEERT: de quads in de inverse die `opFout` binnenkrijgt zijn
// letterlijk dezelfde objecten als die in de gemelde delta. Een WeakMap houdt
// daarom geen enkele quad in leven — verdwijnt hij uit de graaf en uit het log,
// dan verdwijnt zijn entry mee.
//
// Eén invalidatie kan meer dan één stap dragen (de TTL-route spaart delta's op
// tot de debounce afloopt, en een mislukte schrijfactie rolt ze allemaal
// terug), vandaar een verzameling in plaats van één id.
const stapVanQuad = new WeakMap<object, number>();

function onthoudStap(delta: Delta, stap: number): void {
  if (!stap) return;
  for (const q of delta.added || []) stapVanQuad.set(q as object, stap);
  for (const q of delta.removed || []) stapVanQuad.set(q as object, stap);
}

function stappenVan(delta: Delta): number[] {
  const uit = new Set<number>();
  for (const q of [...(delta.added || []), ...(delta.removed || [])]) {
    const stap = stapVanQuad.get(q as object);
    if (stap) uit.add(stap);
  }
  return [...uit];
}

function vergeetSchrijfkant(): void {
  facade = null;
  sync = null;
  gebouwdVoor = { g: null, bron: null };
}

function bouwSchrijfkant(g: Graaf, bron: Bewerkbron): void {
  // Het MUTATIELOG hangt aan de graaf en niet aan de bron: undo/redo is
  // sessiebreed (mutatielog.js) en een bronwissel hoort de geschiedenis niet
  // te wissen. Een nieuwe LADING wel — dan slaan de bewaarde quads op een graaf
  // die niet meer bestaat.
  if (!log || gebouwdVoor.g !== g) log = maakLog(g as unknown as KaleStore);
  sync = maakBronSync([bron], {
    store: g,
    exportTurtle,
    opfsWrite,
    sparqlUpdate,
    updateStatements,
    // HET FOUTPAD (fase C-spec): een geweigerde update mag niet stil blijven
    // staan. De inverse delta gaat terug de KALE graaf in — niet via de facade,
    // want dit is een herstelactie en geen gebruikerswijziging die opnieuw
    // gesynchroniseerd moet worden — daarna de melding en een herrender.
    opFout: (b: Bewerkbron | null, e: Error, inverse: Delta) => {
      const kaal = graaf() as unknown as KaleStore | null;
      if (kaal) {
        kaal.removeQuads(inverse.removed || []);
        kaal.addQuads(inverse.added || []);
      }
      // De graaf is teruggerold, maar het mutatielog kent de mislukte mutatie
      // nog als undo-stap. Laten staan zou betekenen: undo draait een al
      // teruggerolde wijziging nóg eens terug, en redo brengt een triple terug
      // dat nooit is weggeschreven.
      //
      // GERICHT, niet "de laatste" (golf B, checklistpunt 2): de quads van de
      // inverse wijzen de stap(pen) aan die werkelijk mislukten. Levert dat
      // niets op — een fout op een delta die nooit genoteerd is, bijvoorbeeld
      // de inverse van een undo — dan valt er ook niets te vergeten en blijft
      // het log met rust; blindelings de laatste stap poppen zou daar juist een
      // geslaagde bewerking uit de geschiedenis halen.
      if (log) for (const stap of stappenVan(inverse)) log.vergeetStap(stap);
      zetLogVersie((v) => v + 1);
      meld('src.updateFout', {
        bron: (b && (b.name || b.url)) || t('src.bronOnbekend'),
        fout: korteFout(e && e.message),
      });
      // Dezelfde route als voerUit, en om dezelfde reden: de weergave tekent het
      // MODEL, en dat model is hier al gemuteerd (er is optimistisch gerenderd).
      // Zonder deze herrender blijft de geweigerde waarde op het scherm staan
      // terwijl graaf én endpoint de oude dragen. De melding overleeft hem: de
      // schil wist haar alleen bij een LADING of een taalwissel (app.tsx), niet
      // bij een herbouw — dat is het verschil met de bevroren viewer, die haar
      // hier opnieuw moest zetten.
      noteerVoorInvalidatie(inverse);
      return herrenderNaMutatie();
    },
    // De update slaagde, maar een deel paste niet in DELETE/INSERT DATA (blank
    // nodes, zie sparql.js). Stil laten gaan zou de lezer laten denken dat alles
    // bewaard is.
    opSkip: (_b: Bewerkbron, aantal: number) => meld('src.skipMelding', { n: aantal }),
  }) as Wachtrij;

  facade = maakBewerkStore(g, {
    graph: bron.graph,
    onDelta: (d: Delta) => {
      if (log) onthoudStap(d, log.noteer(d) as number);
      zetLogVersie((v) => v + 1);
      noteerVoorInvalidatie(d);
      // De bron-sync mag zijn eigen tempo houden (debounce voor ttl, meteen
      // voor een endpoint); fouten lopen via opFout.
      if (sync) Promise.resolve(sync.verwerk(d)).catch(() => { /* opFout meldde het al */ });
    },
  });
  gebouwdVoor = { g, bron };
}

/** De schrijf-facade van dit moment, of `null` als er niet geschreven kan
 *  worden (geen graaf, geen bewerkbron). Vasthouden mag niet: hij vervalt bij
 *  elke bronwissel en bij elke nieuwe lading. */
export function schrijfstore(): Schrijfstore | null {
  const g = graaf();
  const bron = bewerkbron();
  if (!g || !bron) { vergeetSchrijfkant(); return null; }
  if (!facade || gebouwdVoor.g !== g || gebouwdVoor.bron !== bron) bouwSchrijfkant(g, bron);
  return facade;
}

/** Alles wat nog in de autosave-debounce staat meteen wegschrijven. Hangt (in
 *  de bronnenlaag) aan de downloadknop, aan `beforeunload` en aan het wisselen
 *  van bewerkbron — momenten waarop een wachtende schrijfactie anders verloren
 *  gaat of een verouderd bestand oplevert. */
export function flushBron(bron?: Bewerkbron | null): Promise<void> {
  return sync ? sync.flush(bron || undefined) : Promise.resolve();
}

// --- De bewerk-stand ---------------------------------------------------------

/** Koppel de bronnenlaag aan. Twee dingen gebeuren hier, en verder niets:
 *  de autosave-flush gaat naar `koppelFlush`, en er komt een effect op het
 *  bewerkbron-signaal dat de bewerkstand bijhoudt.
 *
 *  DAT EFFECT IS DE BEVESTIGFLOW, van beide kanten. Verschijnt er een
 *  bewerkbron terwijl de lezer op het aanbod wacht, dan gaat de stand alsnog
 *  aan; verdwijnt de laatste bewerkbron (slotje terug, bron verwijderd, een
 *  her-ingest die de graph verschuift) terwijl de stand aanstaat, dan valt hij
 *  terug op kijken met de reden erbij. De bevroren viewer deed dat met een
 *  `bevestigEditMode()`-aanroep op elk van die plekken; één effect kan er geen
 *  vergeten.
 *
 *  `null` koppelt weer los (tests, en het loslaten van de bewerklaag). */
export function koppelBronbeheer(nieuw: Bronbeheer | null): void {
  if (losKoppeling) { losKoppeling(); losKoppeling = null; }
  if (bronbeheer) bronbeheer.koppelFlush(null);
  bronbeheer = nieuw;
  vergeetSchrijfkant();
  if (!nieuw) return;
  nieuw.koppelFlush(flushBron);
  createRoot((verval) => {
    losKoppeling = verval;
    createEffect(on(() => nieuw.bewerkbron(), (bron) => {
      // De schrijfkant hangt aan DEZE bron; een wissel maakt facade en sync
      // ongeldig (ze wijzen naar de vorige graph).
      vergeetSchrijfkant();
      // `wachtOpHerstel()` staat hier naast `aanbodOpen()` en om dezelfde reden
      // (A9): een lezer die op een bewerkbron wacht hoort hem te krijgen zodra
      // hij er is, of hij nu op het aanbod wachtte of op het OPFS-herstel.
      if (bron && (aanbodOpen() || wachtOpHerstel())) {
        zetWachtOpHerstel(false);
        zetAanbodOpen(false);
        zetEditMode(true);
        return;
      }
      bevestigEditMode();
    }));
    // A9: HET UITGESTELDE OORDEEL, ALSNOG GEVELD. Zodra de bronnenlaag zich
    // afmeldt is `bewerkbron()` een echt antwoord — een bron (de stand gaat aan)
    // of geen bron (het aanbod, met de reden erbij). Eén effect en niet twee
    // aanroepen bij de bronnenlaag: hij kan zich afmelden zonder dat de
    // bewerkbron verandert (eerste bezoek, opgeruimde site-data), en dan vuurt
    // het effect hierboven niet.
    createEffect(() => {
      if (!wachtOpHerstel()) return;
      if (nieuw.herstelBezig && nieuw.herstelBezig()) return;
      zetWachtOpHerstel(false);
      untrack(() => zetEditMode(true));
    });
  });
}

/** De schakelaar (het potlood). Zonder bewerkbron kán de stand niet aan: dat is
 *  geen foutje maar de kern van het bronmodel. De lezer krijgt dan geen
 *  weigering maar een AANBOD — kies of maak een bewerkbron — dat de bronnenlaag
 *  invult en dat via `zetBewerkbron` alsnog in de bewerkstand eindigt.
 *
 *  `bevestig: false` zet de stand STIL: geen aanbod, geen melding. Dat is het
 *  boot-pad (`?edit=1` uit de adresbalk), waar de bevestiging pas hoort zodra
 *  de bronnen geladen zijn — zie `bevestigEditMode`. */
export function zetEditMode(aan: boolean, { bevestig = true }: { bevestig?: boolean } = {}):
boolean {
  const wil = !!aan;
  if (wil && !bewerkbron()) {
    // A9: HET OORDEEL WORDT UITGESTELD, NIET GEVELD. Op F5 staat `?edit=1`
    // meteen in de weergavestore (deeltraject 2) terwijl de bewerkbron uit een
    // asynchrone OPFS-lezing komt. Hier stond alleen de regel hieronder, en die
    // las het lege signaal als "er is geen bron": `weergave.editMode` ging uit,
    // `&edit=1` verdween uit de adresbalk en de lezer kreeg de melding — terwijl
    // zijn lokale kopie een fractie later gewoon verscheen. Er was geen pad dat
    // de stand daarna alsnog aanzette, dus was het verlies blijvend.
    //
    // Wat NIET gebeurt zolang het herstel loopt: de vlag omzetten (dan flikkert
    // de bewerk-CSS en verspringt de adresbalk) en melden (er valt nog niets te
    // melden). Het effect onderaan `koppelBronbeheer` velt het oordeel zodra de
    // bronnenlaag zich afmeldt — beide kanten op.
    if (herstelOnderweg()) { zetWachtOpHerstel(true); return false; }
    if (weergave.editMode) zetWeergave({ editMode: false });
    if (bevestig) {
      zetAanbodOpen(true);
      meld('edit.geenSchrijfbron');
    }
    return false;
  }
  if (weergave.editMode !== wil) zetWeergave({ editMode: wil });
  if (!wil) zetAanbodOpen(false);
  return wil;
}

/** Na elke lading en elke bronwissel: een bewerkstand die niet (meer) kan valt
 *  terug op kijken. Dat is het pad van `?edit=1` op een pagina zonder
 *  bewerkbron, en van de bewerkbron die verdwijnt terwijl de stand aanstaat.
 *  `stil`: geen melding (de aanroeper heeft al iets beters in beeld). */
export function bevestigEditMode({ stil = false }: { stil?: boolean } = {}): void {
  if (!weergave.editMode || bewerkbron()) return;
  // A9, DE VROEGSTE TREFFER. Het effect hieronder draait METEEN bij het laden
  // van de lazy bewerkchunk — dus vóór het boot-pad van de chrome — en kwam op
  // een F5 hier langs met een bewerkbron die nog uit OPFS moest komen. Dezelfde
  // uitstelregel als in `zetEditMode`; zonder deze had de reparatie daar geen
  // effect, want de stand was hier al omgezet.
  if (herstelOnderweg()) { zetWachtOpHerstel(true); return; }
  zetWeergave({ editMode: false });
  if (!stil) meld('edit.geenSchrijfbron');
}

/** Sluit het aanbod zonder een bron te kiezen (de lezer bedacht zich). */
export function sluitAanbod(): void { zetAanbodOpen(false); }

// --- DE GRENS VAN WAT BEWERKBAAR IS ------------------------------------------
// Knoop-grof, en sinds het één-bewerkbron-besluit ondubbelzinnig: een knoop is
// bewerkbaar als hij quads heeft én die allemaal in de graph van de bewerkbron
// staan. Staat een deel ervan elders (een policy waarvan de labels uit een
// alleen-lezen labelbundel komen), dan niet — een wijziging zou de helft van de
// knoop naar een bron schrijven die hem niet bezit. TOEVOEGEN mag wel altijd:
// nieuwe triples gaan per definitie naar de bewerkbron.

/** Staan al deze quads in de bewerkbron? Leeg = niet bewerkbaar: er valt niets
 *  te bewerken dat we bezitten. */
export function quadsInBewerkbron(quads: Quad[]): boolean {
  const bron = bewerkbron();
  if (!bron || !quads || !quads.length) return false;
  return quads.every((q) => q.graph && (q.graph as { value?: string }).value === bron.graph);
}

/** Is deze knoop bewerkbaar? `term` mag een IRI of een term uit de graaf zijn. */
export function bewerkbaar(term: Term | string | null): boolean {
  const g = graaf() as unknown as KaleStore | null;
  const bron = bewerkbron();
  if (!g || !bron || !term) return false;
  const t0 = typeof term === 'string'
    ? ({ termType: 'NamedNode', value: term, id: term } as Term) : term;
  return quadsInBewerkbron(g.getQuads(t0, null, null, null));
}

// --- De herrender na een mutatie ---------------------------------------------
// SAMENVOEGEN, NIET STAPELEN (fase C, taak 9d). Een herrender is niet atomair
// en mutaties komen in salvo's. Zonder slot lopen er twee invalidaties en twee
// DOM-rondes door elkaar heen. De wachtrij is met opzet ÉÉN diep: wie tijdens
// een lopende ronde iets muteert wil de eindstand zien, niet elke tussenstand.
// Meer aanvragen binnen dezelfde ronde vallen dus samen tot precies één extra
// ronde, en iedereen krijgt dezelfde promise terug.

let herrenderLopend: Promise<void> | null = null;
let herrenderNogmaals = false;

/** Wachten tot Solid de DOM heeft bijgewerkt. De invalidatie zet SIGNALEN; wat
 *  daaruit volgt staat er pas na de volgende taak — en juist dát moment maakt
 *  `voerUit` bruikbaar voor wie daarna de DOM leest (een affordance die de focus
 *  terugzet, de scroll-stabiliteitsmeting van golf B, een test). */
const tik = (): Promise<void> => new Promise((r) => { setTimeout(r, 0); });

async function herrenderNu(): Promise<void> {
  const delta = wachtend;
  // NIETS GEMUTEERD, NIETS TE INVALIDEREN (review I-1). Een lege delta zegt de
  // corpusstore terecht niets, en zij herbouwt dan volledig — dat kost een volle
  // buildModel én alle object- en rij-identiteit, precies wat de gerichte weg
  // moet voorkomen. En hij is bereikbaar langs het gewoonste pad dat er is: een
  // veld verlaten zonder wijziging, of een `fn` die gooit vóór zijn eerste
  // mutatie. Dus: geen delta, geen ronde.
  if (!delta.added.length && !delta.removed.length) return;
  wachtend = { added: [], removed: [] };
  // ÉÉN RONDE, NIET DRIE (opruimpunt 22, 10 sep 2026). `invalideer` schrijft
  // achter elkaar het model, de navigatie, de gescopete navigatie en de
  // graafversie; los geschreven levert elk daarvan een eigen update-ronde op, en
  // een kaartrij die ze allemaal (transitief) leest wordt dus meer dan eens
  // opnieuw opgebouwd. Dat is niet alleen werk voor niets: de instanties die
  // daarbij worden weggegooid namen focusverzoeken aan die daarna verdwenen —
  // zie `ui/bewerk/herbouw.test.tsx` voor de meting en `kaartveld.test.tsx` voor
  // wat er stil op misging.
  batch(() => { zetLaatsteInvalidatie(invalideer(delta)); });
  await tik();
}

function herrenderNaMutatie(): Promise<void> {
  if (herrenderLopend) { herrenderNogmaals = true; return herrenderLopend; }
  herrenderLopend = (async () => {
    try {
      do {
        herrenderNogmaals = false;
        await herrenderNu();
      } while (herrenderNogmaals);
    } finally {
      herrenderLopend = null;
      herrenderNogmaals = false;
    }
  })();
  return herrenderLopend;
}

// --- Eén bewerkactie ---------------------------------------------------------

/** Voer één bewerking uit op de bewerkbron.
 *
 *  `groep: true` maakt van een samengestelde mutatie (meer dan één
 *  edit.js-aanroep, of een `setLiteral` die de oude waarde eruit en de nieuwe
 *  erin meldt) ÉÉN undo-stap.
 *
 *  RETOURVORM: een PROMISE die resolvet naar `true` (de mutatie is gedaan) of
 *  `false` (geweigerd of mislukt). De mutatie zelf gebeurt SYNCHROON — zodra
 *  deze functie terugkeert staat zij in de graaf en is zij onderweg naar de
 *  bron; wat de promise toevoegt is het moment waarop de WEERGAVE bij is. Wie
 *  alleen muteert mag hem negeren; wie daarna de DOM leest, awaitet hem.
 *  Bewust geen synchrone boolean ernaast: twee retourwaarden voor één aanroep is
 *  precies de vorm waarin `if (voerUit(...))` stilzwijgend altijd waar wordt. */
export function voerUit(
  fn: (store: Schrijfstore) => void, { groep = false }: { groep?: boolean } = {},
): Promise<boolean> {
  const f = schrijfstore();
  if (!f) { meld('edit.geenSchrijfbron'); return Promise.resolve(false); }
  try {
    // ÉÉN RONDE VOOR DE HELE GROEP (opruimpunt 22). `onDelta` bumpt de logversie
    // per delta — een `zetLiteral` levert er twee (oud eruit, nieuw erin) — en de
    // regel hieronder nog eens één na het sluiten van de groep. Zonder batch zijn
    // dat drie update-rondes vóór de invalidatie ook nog begint. Het is één
    // bewerking, dus het hoort één ronde te zijn; de mutatie zelf blijft
    // synchroon, want `batch` stelt alleen de doorgifte van de signalen uit.
    batch(() => {
      if (groep && log) log.groep(() => fn(f)); else fn(f);
    // DE LOGVERSIE NÓG EEN KEER, NA HET SLUITEN VAN DE GROEP (golf B).
    //
    // `onDelta` bumpt hem al per delta, maar binnen een groep is de stap dan
    // nog niet afgesloten: `noteer` legt de delta op de lopende lijst en pas de
    // `finally` van `log.groep` duwt hem op de gedaan-stapel. Wie op dat moment
    // `kanOngedaan()` leest — en dat is precies wat een undo-knop doet die aan
    // het signaal hangt — krijgt `false` te zien, en daarna komt er geen
    // volgende bump meer.
    //
    // GEMETEN IN DE GEBOUWDE APP (golf B, lane-velden): de undo-knop bleef
    // permanent op zijn uit-vorm staan terwijl `kanOngedaan()` bij een directe
    // aanroep `true` gaf en de knop bij een klik gewoon terugdraaide. Het
    // effect vuurde wél (twee keer, één per delta) maar zag beide keren de nog
    // niet gesloten groep. Elke `voerUit` gebruikt `groep: true`, dus dit raakte
    // élke bewerking.
      zetLogVersie((v) => v + 1);
    });
  } catch (e) {
    // De mutatielaag gooit bij een onmogelijke bewerking (onbekende IRI, een
    // knoop die er niet meer is). De graaf kan halverwege staan; de herrender
    // laat zien wat er wél gebeurd is, en undo brengt de rest terug.
    // Ook hier: de groep is afgesloten (log.groep bewaart wat er wél gemuteerd
    // is), dus de stand van undo/redo is veranderd.
    zetLogVersie((v) => v + 1);
    meld('edit.mutatieFout', { fout: korteFout(e instanceof Error ? e.message : e) });
    return herrenderNaMutatie().then(() => false, herrenderMislukt);
  }
  return herrenderNaMutatie().then(() => true, herrenderMislukt);
}

// EEN AFGEKETSTE INVALIDATIE IS GEEN GESLAAGDE BEWERKING (review I-2). Gooit de
// herbouw halverwege, dan is `setModel` niet gedraaid terwijl de globale slagen
// de hergebruikte objecten van het LEVENDE model al hebben herschreven: de lezer
// houdt een half geannoteerd model op het scherm. Dat mag niet stil, en het mag
// zeker geen `true` opleveren — undo/redo (`draai`) liet dezelfde fout al door,
// dus de twee paden lopen nu gelijk.
function herrenderMislukt(e: unknown): false {
  console.error('bewerk: de herbouw na een mutatie ketste af', e);
  meld('edit.mutatieFout', { fout: korteFout(e instanceof Error ? e.message : e) });
  return false;
}

// --- Undo/redo ---------------------------------------------------------------
// Het mutatielog draait de graaf zelf terug (het houdt de KALE graaf vast, niet
// de facade — anders zou de inverse als nieuwe gebruikerswijziging worden
// genoteerd); wat het teruggeeft is de inverse delta, en die moet alsnog naar de
// bron: het OPFS-bestand of het endpoint. Zonder die stap klopt het scherm wel
// en het bestand niet.

/** Valt er iets terug te draaien? Reactief: de knoppen van de bewerkchrome
 *  hangen eraan. */
export function kanOngedaan(): boolean {
  void logVersie();
  return !!log && log.kanUndo();
}

export function kanOpnieuw(): boolean {
  void logVersie();
  return !!log && log.kanRedo();
}

async function draai(richting: 'undo' | 'redo'): Promise<boolean> {
  // De schrijfstore even aanraken: log en sync horen bij deze graaf en deze
  // bewerkbron, en na een lading bestaan ze nog niet.
  schrijfstore();
  if (!log) return false;
  const delta: Delta | null = richting === 'undo' ? log.undo() : log.redo();
  zetLogVersie((v) => v + 1);
  if (!delta) return false;
  noteerVoorInvalidatie(delta);
  if (sync) {
    try { await sync.verwerk(delta); } catch { /* opFout meldde het al */ }
  }
  await herrenderNaMutatie();
  return true;
}

/** Draai de laatste bewerking terug. `false` = er viel niets terug te draaien. */
export const ongedaan = (): Promise<boolean> => draai('undo');

/** Voer de laatst teruggedraaide bewerking opnieuw uit. */
export const opnieuw = (): Promise<boolean> => draai('redo');

/** Alleen voor tests: de sessie leegmaken (koppeling, log, sync, stand). */
export function resetBewerkstand(): void {
  koppelBronbeheer(null);
  zetAanbodOpen(false);
  zetWachtOpHerstel(false);
  zetBewerkMelding(null);
  zetLaatsteInvalidatie(null);
  log = null;
  wachtend = { added: [], removed: [] };
  vergeetSchrijfkant();
  if (weergave.editMode) zetWeergave({ editMode: false });
}

