// Facade om de N3.Store voor bewerkacties: routeert schrijfacties naar de
// graph van de actieve schrijfbron en meldt elke wijziging als delta
// ({added, removed}) — de voedingsbron voor autosave, SPARQL Update en undo.
//
// De bewerkfuncties in edit.js schrijven met drie argumenten
// (`store.addQuad(s, p, o)`) en landen dus in de default graph. Sinds de
// bronnenlaag staat elke bron in een eigen named graph; deze facade hangt die
// graph er alsnog aan, zonder dat edit.js van bronnen hoeft te weten.
// Leesmethoden en eigenschappen lopen ongewijzigd door naar de store.
//
// CONTRACT — de facade is uitsluitend de bewerk-ingang (het edit.js-pad).
// Laadpaden (`addSource`, lazy SPARQL-bijlading, worker-hydratie) schrijven
// altijd op de kále store: zij brengen brongegevens binnen, geen
// gebruikersmutaties, en zouden anders in de werkgraph belanden én als
// wijziging worden weggeschreven. De handhaving daarvan hoort bij de taak die
// de facade aansluit; hier staat alleen de afspraak.
import * as N3 from 'n3';

const { namedNode, quad, defaultGraph } = N3.DataFactory;

const isTerm = (x) => Boolean(x) && typeof x.termType === 'string';
const isQuad = (x) => Boolean(x) && x.termType === 'Quad';

// De schrijfmethoden die edit.js gebruikt, elk als fabriek over de context van
// één facade. Deze tabel is de enige bron van waarheid: `GEROUTEERDE_METHODEN`
// wordt eruit afgeleid, dus de lijst kan niet uit de pas lopen met het gedrag.
//
// Store.addQuad/removeQuad geven true terug als er werkelijk iets veranderde;
// addQuads/removeQuads geven niets terug. Daarom lopen de bundelvarianten hier
// zelf door de quads: zo bevat de delta alleen echte wijzigingen (een dubbele
// add of een remove van iets dat er niet staat levert geen delta op).
const SCHRIJF_WRAPPERS = {
  addQuad: ({ store, bouwQuad, routeer, meld }) => (s, p, o, gr) => {
    const q = routeer(bouwQuad(s, p, o, gr));
    const nieuw = store.addQuad(q);
    if (nieuw !== false) meld([q], []);
    return nieuw;
  },

  addQuads: ({ store, routeer, meld }) => (quads) => {
    const added = [];
    for (const q0 of quads) {
      const q = routeer(q0);
      if (store.addQuad(q) !== false) added.push(q);
    }
    meld(added, []);
  },

  removeQuad: ({ bouwQuad, verwijder, meld }) => (s, p, o, gr) => {
    const weg = verwijder(bouwQuad(s, p, o, gr));
    if (weg) meld([], [weg]);
    return Boolean(weg);
  },

  removeQuads: ({ verwijder, meld }) => (quads) => {
    const removed = [];
    for (const q0 of quads) {
      const weg = verwijder(q0);
      if (weg) removed.push(weg);
    }
    meld([], removed);
  },
};

export const GEROUTEERDE_METHODEN = Object.keys(SCHRIJF_WRAPPERS);

// Store-methoden die de graaf wijzigen buiten de gerouteerde vier om. Ze zouden
// rechtstreeks op de store schrijven: geen graph-routering, geen delta, dus een
// autosave die de wijziging nooit ziet. Liever luid falen dan stil verliezen.
export const GEBLOKKEERDE_METHODEN = [
  'add', 'addAll', 'delete', 'deleteMatches', 'deleteGraph',
  'import', 'remove', 'removeMatches',
];

export function bewerkStore(store, { graph = null, onDelta = null } = {}) {
  const g = graph ? (isTerm(graph) ? graph : namedNode(String(graph))) : null;

  // Quads zonder eigen graph-term horen in de werkgraph. Een aanroep die zelf
  // een graph meegeeft (bv. een quad die al uit de store komt) blijft staan.
  const routeer = (q) => (g && (!q.graph || q.graph.termType === 'DefaultGraph')
    ? quad(q.subject, q.predicate, q.object, g)
    : q);

  // Verwijderen mag niet blind routeren: aan een quad zonder graph-term is niet
  // te zien of hij handgemaakt is (en dus de werkgraph bedoelt) of werkelijk in
  // de default graph staat — bijgeladen brongegevens doen dat laatste. Daarom
  // eerst de exacte quad proberen en pas als die er niet is de gerouteerde
  // variant. Geeft de werkelijk verwijderde quad terug, of null.
  const verwijder = (q0) => {
    if (store.removeQuad(q0) !== false) return q0;
    const q = routeer(q0);
    return (q !== q0 && store.removeQuad(q) !== false) ? q : null;
  };

  const meld = (added, removed) => {
    if (onDelta && (added.length || removed.length)) onDelta({ added, removed });
  };

  // addQuad(s, p, o, g?) én addQuad(quad) — N3 kent beide vormen. Bouwt de quad
  // zoals de aanroeper hem bedoelde; routeren gebeurt pas daarna, per bewerking.
  const bouwQuad = (s, p, o, gr) => (isQuad(s) && p === undefined
    ? s
    : quad(s, p, o, gr || defaultGraph()));

  const ctx = { store, routeer, verwijder, meld, bouwQuad };
  const wrap = Object.create(null);
  for (const naam of GEROUTEERDE_METHODEN) wrap[naam] = SCHRIJF_WRAPPERS[naam](ctx);
  for (const naam of GEBLOKKEERDE_METHODEN) {
    wrap[naam] = () => {
      throw new Error(`bewerkstore: store.${naam}() omzeilt de bewerkstore `
        + '(geen graph-routering, geen delta) — gebruik addQuad/addQuads/removeQuad/removeQuads');
    };
  }

  // Methoden van de store worden aan de store gebonden (en gecached, zodat
  // `facade.getQuads === facade.getQuads` blijft gelden); zo werkt `this` ook
  // als een aanroeper de methode losmaakt.
  const gebonden = new Map();

  return new Proxy(store, {
    get(target, prop) {
      if (prop in wrap) return wrap[prop];
      const v = Reflect.get(target, prop, target);
      if (typeof v !== 'function') return v;
      if (!gebonden.has(prop)) gebonden.set(prop, v.bind(target));
      return gebonden.get(prop);
    },
    set(target, prop, value) {
      return Reflect.set(target, prop, value, target);
    },
    has(target, prop) {
      return prop in wrap || prop in target;
    },
  });
}
