// Delta-routering: een wijziging uit de bewerkstore ({added, removed}) naar de
// bron waar hij vandaan komt.
//
// De bewerkstore (bewerkstore.js) hangt aan elke geschreven quad de graph van
// de schrijfbron; sinds de bronnenlaag is die graph dus het routeeradres. Deze
// laag groepeert de delta per graph, zoekt de bijbehorende bron op en stuurt
// elke deelgroep naar zijn bestemming:
//
//   ttl-bron     -> gedebounced (default 800 ms) exportTurtle(store, {graph})
//                   + opfsWrite(bron.opfs, ttl): de hele graph wordt opnieuw
//                     weggeschreven, dus de losse delta-quads doen er voor de
//                     inhoud niet toe — alleen voor het terugdraaien.
//   sparql-bron  -> direct updateStatements(deelDelta) -> sparqlUpdate(
//                     bron.updateUrl, query): een endpoint kan niet wachten op
//                     een debounce zonder dat de gebruiker ondertussen denkt
//                     dat het geslaagd is.
//   read-bron,
//   onbekende
//   graph        -> opFout: er is geen bestemming, dus de wijziging kán niet
//                   blijven staan. In fase B hoort dit niet voor te komen (de
//                   UI biedt alleen schrijfbronnen aan), maar stil laten vallen
//                   is het ergste wat er met een gebruikerswijziging kan
//                   gebeuren.
//
// VOLGORDE: per bron loopt alles door één wachtrij (zie `keten`), want de
// bewerkstore meldt delta's synchroon en één bewerking kan als remove-dan-add
// in dezelfde tick binnenkomen. Zonder wachtrij kunnen twee updates elkaar
// inhalen en wist de laatste de data van de eerste — stil, zonder opFout.
//
// BEGRENSDE DEBOUNCE + FLUSH: elke nieuwe delta herplant de timer, maar nooit
// voorbij `maxWaitMs` (default 4000) na de oudste nog niet weggeschreven
// wijziging; een aaneengesloten reeks bewerkingen kan de autosave dus niet
// onbeperkt uitstellen. Daarnaast schrijft `flush(bron?)` alles wat in de
// debounce staat meteen weg — taak 8 hangt die aan het downloaden van een
// bron, aan `beforeunload` en aan het wisselen van schrijfbron.
//
// TERUGDRAAIEN: elk faalpad roept opFout(bron, error, inverseDelta) aan. De
// inverse is {added: removed, removed: added} en is BEPERKT tot de quads van
// die ene bron — raakt een delta twee bronnen en weigert er één, dan blijft de
// geslaagde helft staan. De aanroeper (de UI) past de inverse toe op de store
// en meldt de fout; deze laag muteert zelf niets.
//
// OVERGESLAGEN TRIPLES: updateStatements geeft {query, skipped}. `skipped`
// telt de blank-node-triples die SPARQL Update niet aankan (zie sparql.js). De
// update slaagt dan wél, maar is onvolledig; dat gaat via de optionele
// opSkip(bron, aantal) naar de UI. opSkip volgt op een GESLAAGDE verzending:
// bij een weigering rolt de hele deelgroep toch terug en zou een melding over
// een deelverlies alleen verwarren.
//
// DOM-vrij en zonder imports: store, exportTurtle, opfsWrite, sparqlUpdate,
// updateStatements en de terugmeldingen komen allemaal via `deps` binnen, zodat
// dit in Node testbaar is en de viewer de echte implementaties koppelt. Ook de
// klok (`now`, default Date.now) en `setTimeout` zijn injecteerbaar; de tests
// draaien daarmee zonder echte tijd. De verplichte deps worden bij constructie
// gecontroleerd — ontbreekt er een, dan meteen een Error met de namen erbij.

export const DEBOUNCE_MS = 800;
// Bovengrens op het debounce-venster: tussen de eerste nog niet weggeschreven
// wijziging en de schrijfactie mag hooguit zoveel tijd zitten. Zonder die cap
// schuift een aaneengesloten reeks bewerkingen (elke toetsaanslag herplant de
// timer) de autosave onbeperkt voor zich uit.
export const MAX_WAIT_MS = 4000;

// Deps die er écht moeten zijn: zonder deze faalt niet de constructie maar pas
// de eerste delta, en dan met een TypeError diep in een timer. Liever meteen
// luid, met de namen erbij.
const VERPLICHTE_DEPS = [
  'store', 'exportTurtle', 'opfsWrite', 'sparqlUpdate', 'updateStatements', 'opFout',
];

// De graph van een bron als string: de bronnenlijst mag hem als string of als
// RDF-term aanleveren. exportTurtle verwacht een string (het maakt er zelf een
// namedNode van), en quad.graph.value is ook een string — één normalisatie dus.
function graphNaam(bron) {
  const g = bron && bron.graph;
  if (g == null) return '';
  return g.value != null ? String(g.value) : String(g);
}

// Delta -> Map van graph-naam naar {added, removed}. Quads zonder graph-term
// (default graph) krijgen de lege sleutel en lopen zo in het onbekende-graph-
// pad: ze hebben geen bron en horen niet stil te verdwijnen.
function groepeerPerGraph(delta) {
  const groepen = new Map();
  const vul = (quads, veld) => {
    for (const q of quads || []) {
      const g = q && q.graph && q.graph.value ? q.graph.value : '';
      let groep = groepen.get(g);
      if (!groep) { groep = { added: [], removed: [] }; groepen.set(g, groep); }
      groep[veld].push(q);
    }
  };
  vul(delta && delta.added, 'added');
  vul(delta && delta.removed, 'removed');
  return groepen;
}

export function maakBronSync(bronnen, deps = {}) {
  const {
    store, exportTurtle, opfsWrite, sparqlUpdate, updateStatements,
    opFout, opSkip = null,
    setTimeout: plan = ((fn, ms) => globalThis.setTimeout(fn, ms)),
    now = Date.now,
    debounceMs = DEBOUNCE_MS,
    maxWaitMs = MAX_WAIT_MS,
  } = deps;

  const ontbreekt = VERPLICHTE_DEPS.filter((naam) => deps[naam] == null);
  if (ontbreekt.length) {
    throw new Error('maakBronSync: ontbrekende deps: ' + ontbreekt.join(', '));
  }

  // graph -> bron. De eerste bron met een graph wint: bij een dubbele graph in
  // de bronnenlijst is dat de deterministische keuze (en die dubbeling is zelf
  // een fout in de bronnenlijst, niet iets om hier op te lossen).
  const perGraph = new Map();
  for (const bron of bronnen || []) {
    const g = graphNaam(bron);
    if (g && !perGraph.has(g)) perGraph.set(g, bron);
  }

  // Openstaande ttl-schrijfacties: bron -> {added, removed, generatie, eerste}.
  // De delta's stapelen op tot de timer afloopt, zodat een mislukte
  // schrijfactie álles kan terugdraaien wat sinds de vorige geslaagde write is
  // gebeurd; `eerste` is het tijdstip van de oudste opgespaarde wijziging en
  // draagt de maxWaitMs-cap.
  const wachtend = new Map();
  // Monotone teller per bron. De geïnjecteerde setTimeout kent geen
  // clearTimeout, dus annuleren gebeurt door de generatie te verhogen: een
  // timer die afloopt terwijl er een nieuwere gepland staat, doet niets.
  const generaties = new Map();

  // SERIALISATIE — één wachtrij per bron. De bewerkstore meldt delta's
  // synchroon en gooit de returnwaarde weg (bewerkstore.js meld()), en edit.js
  // vuurt bewerkingen als remove-dan-add in dezelfde tick af. Zonder wachtrij
  // gaan die als twee gelijktijdige POSTs de deur uit en kan de INSERT vóór de
  // DELETE landen — dan wist de tweede update net weggeschreven data, stil en
  // zonder opFout. Hetzelfde geldt voor twee OPFS-writes die elkaar inhalen:
  // de oudere export zou als laatste op schijf kunnen belanden. Alles wat naar
  // één bron schrijft, loopt daarom door deze keten.
  const keten = new Map();

  function inWachtrij(bron, taak) {
    const vorige = keten.get(bron) || Promise.resolve();
    // .then(taak, taak): een gefaalde voorganger mag de wachtrij niet breken —
    // taken vangen hun eigen fouten al af en negeren hun argument.
    const volgende = vorige.then(taak, taak);
    keten.set(bron, volgende);
    volgende.then(() => { if (keten.get(bron) === volgende) keten.delete(bron); });
    return volgende;
  }

  const nieuweGeneratie = (bron) => {
    const generatie = (generaties.get(bron) || 0) + 1;
    generaties.set(bron, generatie);
    return generatie;
  };

  const meldFout = (bron, error, groep) => {
    const inverse = { added: groep.removed, removed: groep.added };
    if (typeof opFout !== 'function') throw error; // liever luid dan stil
    opFout(bron, error, inverse);
  };

  async function schrijfTtl(bron, generatie) {
    const staat = wachtend.get(bron);
    if (!staat || staat.generatie !== generatie) return; // opgevolgd door een nieuwere delta
    // Vóór het await weghalen: wijzigingen die tijdens het schrijven
    // binnenkomen horen bij de vólgende schrijfactie, niet bij deze.
    wachtend.delete(bron);
    try {
      const ttl = exportTurtle(store, { graph: graphNaam(bron) });
      await opfsWrite(bron.opfs, ttl);
    } catch (e) {
      meldFout(bron, e, staat);
    }
  }

  function planTtl(bron, groep) {
    const staat = wachtend.get(bron) || { added: [], removed: [], eerste: now() };
    staat.added.push(...groep.added);
    staat.removed.push(...groep.removed);
    const generatie = nieuweGeneratie(bron);
    staat.generatie = generatie;
    wachtend.set(bron, staat);
    // Wachttijd: de gewone debounce, maar nooit voorbij het punt waarop de
    // oudste opgespaarde wijziging maxWaitMs oud is. Zo blijft herplannen bij
    // een aaneengesloten reeks bewerkingen begrensd.
    const rest = staat.eerste + maxWaitMs - now();
    const wachttijd = Math.max(0, Math.min(debounceMs, rest));
    plan(() => inWachtrij(bron, () => schrijfTtl(bron, generatie)), wachttijd);
  }

  async function naarEndpoint(bron, groep) {
    let uitkomst;
    try {
      // Gooit bij een IRI die niet veilig in een update past — dan is er nog
      // niets verzonden en draait de hele deelgroep terug.
      uitkomst = updateStatements({ added: groep.added, removed: groep.removed });
    } catch (e) {
      meldFout(bron, e, groep);
      return;
    }
    const { query = '', skipped = 0 } = uitkomst || {};
    if (query) {
      try {
        await sparqlUpdate(bron.updateUrl, query);
      } catch (e) {
        meldFout(bron, e, groep);
        return;
      }
    }
    if (skipped && typeof opSkip === 'function') opSkip(bron, skipped);
  }

  // Verwerkt één delta. Wacht op de endpoint-routes (die kunnen weigeren en
  // moeten dus vóór de volgende gebruikersactie hun opFout hebben gedaan); de
  // ttl-routes worden alleen gepland en lopen na de debounce.
  async function verwerk(delta) {
    for (const [graph, groep] of groepeerPerGraph(delta)) {
      const bron = perGraph.get(graph);
      if (!bron) {
        meldFout(null, new Error('bron-sync: wijziging in een graph zonder bron'
          + (graph ? ` ("${graph}")` : ' (default graph)')
          + ' — nergens om naar weg te schrijven'), groep);
        continue;
      }
      if (bron.modus !== 'readwrite') {
        meldFout(bron, new Error(`bron-sync: bron "${bron.url || graph}" is alleen-lezen`
          + ' — wijziging kan niet worden bewaard'), groep);
        continue;
      }
      if (bron.soort === 'ttl') {
        // Een schrijfbare ttl-bron zonder lokale kopie is een fout in de
        // bronnenlijst; zonder bestandsnaam is er niets om naar te schrijven.
        if (!bron.opfs) {
          meldFout(bron, new Error(`bron-sync: bron "${bron.url || graph}" heeft geen`
            + ' lokale kopie (opfs) om naar weg te schrijven'), groep);
          continue;
        }
        planTtl(bron, groep);
      }
      else if (bron.soort === 'sparql') {
        // In de wachtrij én er hier op wachten: de aanroeper mag ervan uitgaan
        // dat na `await verwerk(...)` deze bron klaar is (of opFout heeft gehad).
        await inWachtrij(bron, () => naarEndpoint(bron, groep));
      }
      else {
        meldFout(bron, new Error(`bron-sync: onbekende bronsoort "${bron.soort}"`
          + ` voor "${bron.url || graph}"`), groep);
      }
    }
  }

  // Schrijft wat er in de debounce staat meteen weg: alle bronnen, of alleen
  // `bron`. Taak 8 hangt dit aan het downloaden van een bron, aan beforeunload
  // en aan het wisselen van schrijfbron — momenten waarop een wachtende
  // schrijfactie anders verloren gaat of een verouderd bestand oplevert.
  // De belofte resolvet ná de writes; fouten lopen zoals altijd via opFout.
  // Ook een lopende endpoint-update wordt afgewacht: flush() betekent "alles
  // wat deze laag nog moest doen, is gedaan".
  function flush(bron) {
    const doelen = bron ? [bron] : new Set([...wachtend.keys(), ...keten.keys()]);
    const beloftes = [];
    for (const b of doelen) {
      const staat = wachtend.get(b);
      if (!staat) {
        // Niets in de debounce: alleen wachten tot een eventuele lopende
        // schrijfactie of update van deze bron klaar is.
        beloftes.push(keten.get(b) || Promise.resolve());
        continue;
      }
      // Nieuwe generatie: de hangende timer vindt straks geen wachtstaat meer
      // (of een nieuwere generatie) en doet niets.
      const generatie = nieuweGeneratie(b);
      staat.generatie = generatie;
      beloftes.push(inWachtrij(b, () => schrijfTtl(b, generatie)));
    }
    return Promise.all(beloftes).then(() => undefined);
  }

  return { verwerk, flush };
}
